#define VOCAL_TEST_NO_MAIN 1
#include "support.h"
static int32_t out[CTL*2];
static track_t*setup_level(int cutoff){memset(trk,0,sizeof trk);memset(&song,0,sizeof song);host_tracks_init();track_t*t=&trk[0];host_preset(t,ENGI_HARMONY,0);harmony_defaults(t->p);t->p[P_E0]=SMP_NSETS;t->p[P_E2]=12;t->p[P_E4]=cutoff;t->p[P_VOICE]=V_LEGATO;t->p[P_CHOR]=t->p[P_DLY]=t->p[P_REV]=t->p[P_DIST]=0;return t;}
static double measure(int cutoff,unsigned*gain){track_t*t=setup_level(cutoff);trk_note_on(t,60,127);double energy=0;for(unsigned b=0;b<FS*2/CTL;b++){mix_block(out,CTL);for(unsigned i=0;i<CTL*2;i++){assert(out[i]>=-32768&&out[i]<=32767);if(b>FS/CTL)energy+=(double)out[i]*out[i];}assert(voices_busy()==5);for(unsigned k=0;k<5;k++)assert(!(t->v[k].ph[2]&0x80000000u));}*gain=harm(t)->singer[0].countdown[1];return energy;}
int main(int argc,char**argv){assert(argc==2);for(int minor=0;minor<2;minor++)for(int root=0;root<12;root++)for(int note=-256;note<256;note++){static const int notes[2][7]={{0,2,4,5,7,9,11},{0,2,3,5,7,8,10}};int expected=0;for(int k=0;k<7;k++)expected|=((note-root+120)%12==notes[minor][k]);assert(allowed(note,root,minor)==expected);}puts("Major/minor membership exactly matches prior lookup across signed note range.");fixture(argv[1]);unsigned a,b;double open=measure(127,&a),closed=measure(0,&b);assert(closed<open&&a==b);printf("Filter remains effective; normalizer gain unaffected by cutoff (%u == %u).\n",a,b);
 track_t*t=setup_level(127);trk_note_on(t,60,127);for(unsigned k=0;k<1000;k++)mix_block(out,CTL);unsigned age=harm(t)->source.samples;t->p[P_E1]=72;mix_block(out,CTL);assert(harm(t)->decoder.ph[2]==72&&harm(t)->source.samples>age);for(unsigned k=0;k<5;k++)assert(t->v[k].s[5]==H_FADE-CTL);for(unsigned k=0;k<1000;k++)mix_block(out,CTL);trk_note_on(t,72,127);for(unsigned k=0;k<1000;k++)mix_block(out,CTL);assert(voices_busy()==5);puts("Live ROOT changes crossfade without restarting source; full-velocity packed envelopes and octave legato retain five sections.");
 for(unsigned lead=0;lead<2;lead++)for(unsigned note=24;note<=96;note+=12){t=setup_level(127);t->p[P_LEVEL]=127;t->p[P_LDECAY0]=(int)lead;trk_note_on(t,note,127);for(unsigned k=0;k<FS*2/CTL;k++){mix_block(out,CTL);assert(harm(t)->singer[0].countdown[1]<=8192u);for(unsigned i=0;i<CTL*2;i++)assert(out[i]>-32768&&out[i]<32767);}assert(voices_busy()==4+lead);}
 puts("Extreme-register full-velocity choir stays bounded, including LEAD count zero.");
 return 0;}
